// Expo config plugin: raise the iOS deployment target of any CocoaPods target
// that is set below a minimum.
//
// Why: Xcode 27 refuses to build pod targets below iOS 15.0, but a few pods
// (resource bundles in Sentry, SDWebImage, AsyncStorage, react-native-maps)
// still declare 9.0 to 13.4. `ios/` is regenerated by `expo prebuild`, so the
// fix has to live here and be written into the Podfile every time.
const { withDangerousMod } = require('expo/config-plugins');
const fs = require('fs');
const path = require('path');

const MARKER = '# [with-pod-min-deployment-target]';
const MIN_VERSION = '15.1'; // React Native 0.81's own minimum

const SNIPPET = `
    ${MARKER}
    installer.pods_project.targets.each do |target|
      target.build_configurations.each do |build_config|
        current = build_config.build_settings['IPHONEOS_DEPLOYMENT_TARGET']
        if current && Gem::Version.new(current) < Gem::Version.new('${MIN_VERSION}')
          build_config.build_settings['IPHONEOS_DEPLOYMENT_TARGET'] = '${MIN_VERSION}'
        end
      end
    end`;

// Inserted right after the react_native_post_install(...) call.
const ANCHOR = /(react_native_post_install\([\s\S]*?\n\s*\))/;

function patchPodfile(contents) {
  if (contents.includes(MARKER)) return contents; // already patched
  if (!ANCHOR.test(contents)) {
    throw new Error(
      'with-pod-min-deployment-target: could not find react_native_post_install(...) in the Podfile. ' +
        'The React Native Podfile template changed; update plugins/with-pod-min-deployment-target.js.',
    );
  }
  return contents.replace(ANCHOR, `$1\n${SNIPPET}`);
}

module.exports = function withPodMinDeploymentTarget(config) {
  return withDangerousMod(config, [
    'ios',
    (modConfig) => {
      const podfilePath = path.join(modConfig.modRequest.platformProjectRoot, 'Podfile');
      const contents = fs.readFileSync(podfilePath, 'utf8');
      fs.writeFileSync(podfilePath, patchPodfile(contents));
      return modConfig;
    },
  ]);
};

module.exports.patchPodfile = patchPodfile;
